sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
uniform float angle;
half4 main(float2 xy) {
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a)) * strength * beat * min(size.x, size.y);
    half4 r = image.eval(xy + d);
    half4 g = image.eval(xy);
    half4 b = image.eval(xy - d);
    return half4(r.r, g.g, b.b, max(max(r.a, g.a), b.a));
}
